select urm.user_id from t_user_role_map urm inner join t_role r on r.role_id = urm.role_id inner join t_user u on u.user_id = urm.user_id where upper(r.name) = 'EXPERT' and coalesce(u.status, 0) = 0 and urm.user_id in
